perl - <<'PL'
use strict;
use warnings;
open my $fh, '<', '/app/regex.txt' or die $!;
local $/;
my $pattern = <$fh>;
$pattern =~ s/\s+\z//;
my $re = qr/$pattern/m;

my @valid_dates = qw(
  2024-01-31 2024-02-29 2024-03-31 2024-04-30 2024-05-31 2024-06-30
  2024-07-31 2024-08-31 2024-09-30 2024-10-31 2024-11-30 2024-12-31
);
my @invalid_dates = qw(
  2024-00-01 2024-01-00 2024-01-32 2024-02-00 2024-02-30
  2024-03-32 2024-04-31 2024-05-32 2024-06-31 2024-07-32
  2024-08-32 2024-09-31 2024-10-32 2024-11-31 2024-12-32
  2024-13-01 24-01-01 2024-1-01 2024-01-1
);
for my $date (@valid_dates) {
    my $line = "INFO 192.0.2.1 $date";
    die "valid date rejected: $date\n" unless $line =~ /$re/;
}
for my $date (@invalid_dates) {
    my $line = "INFO 192.0.2.1 $date";
    die "invalid date accepted: $date\n" if $line =~ /$re/;
}

my @valid_ips = qw(0.0.0.0 9.10.99.100 199.200.249.250 255.255.255.255);
my @invalid_ips = qw(00.0.0.0 1.02.3.4 1.2.003.4 256.0.0.1 1.2.3.256 999.1.1.1);
for my $ip (@valid_ips) {
    die "valid IP rejected: $ip\n" unless "INFO $ip 2024-01-01" =~ /$re/;
}
for my $ip (@invalid_ips) {
    die "invalid IP accepted: $ip\n" if "INFO $ip 2024-01-01" =~ /$re/;
}
print "date-range and IPv4-boundary checks: passed\n";
PL
